# The skew-prone pattern: two separate implementations of "the same" feature
def training_pipeline_feature(user_id):
    # batch job, runs nightly, averages over a calendar month
    return avg_spend(user_id, days=30, calendar_aligned=True)

def serving_feature(user_id):
    # online service, written by a different team, averages over
    # a rolling 30-day window instead — subtly different!
    return avg_spend(user_id, days=30, calendar_aligned=False)

# A feature store collapses this into one definition, used by both:
class FeatureStore:
    def avg_spend_30d(self, user_id, as_of=None):
        # one definition; as_of=None means "now" (online),
        # as_of=<timestamp> means "historical" (offline, for training)
        return self._compute_avg_spend(user_id, days=30, as_of=as_of)
