def validate_dataset(df, schema, historical_stats):
    errors = []

    # Schema validation
    for col, expected_type in schema.items():
        if col not in df.columns:
            errors.append(f"missing required column: {col}")
        elif df[col].dtype != expected_type:
            errors.append(f"{col} has wrong type: {df[col].dtype}")

    # Statistical validation
    if abs(len(df) - historical_stats["avg_row_count"]) > historical_stats["row_count_tolerance"]:
        errors.append("row count is far outside the historical norm")
    if df["amount"].isnull().mean() > historical_stats["max_null_rate"]:
        errors.append("missing-value rate for 'amount' exceeds historical norm")

    if errors:
        raise ValueError(f"data validation failed, halting pipeline: {errors}")
    return df  # only reaches training if validation actually passed
